const hs: HsCodeSuggester = {
  async suggest({ allowedCodes }) {
    const code = allowedCodes.find((c) => c.code10 === "8539520009");
    if (!code) return { candidates: [] };
    return {
      candidates: [
        {
          code10: code.code10,
          officialNameUz: code.officialNameUz,
          signals: [
            { name: "list", detail: "code is in the official list slice" },
            { name: "invoice_prefix", detail: "8539 matches the invoice text" },
          ],
        },
      ],
    };
  },
};

const questions: ClarifyingQuestionGenerator = {
  async questions({ table }) {
    return { questionIds: table.slice(0, 1).map((row) => row.id) };
  },
};

const paraphraser: MessageParaphraser = {
  async paraphrase({ libraryId, libraryTextUz, locale }) {
    if (!libraryId) {
      const text = locale === "ru" ? "Неизвестное сообщение." : "Nomaʼlum xabar.";
      return { text, disclaimer: "YuklaGo izohi, rasmiy kod emas" };
    }
    return { text: libraryTextUz, disclaimer: "YuklaGo izohi, rasmiy kod emas" };
  },
};

const translator: DisplayTranslator = {
  async translate({ text }) {
    return { text };
  },
};

export const stubAiPorts: AiPorts = {
  masker,
  classifier,
  extractor,
  hs,
  questions,
  paraphraser,
  translator,
};
